222	    @Override
223	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
224	        Owner owner = this.clinicService.findOwnerById(ownerId);
225	        if (owner == null) {
226	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
227	        }
228	        HttpHeaders headers = new HttpHeaders();
