@WithMockUser(roles = "OWNER_ADMIN")
void createOwnerSameHouseholdDifferentTelephoneAllowed() throws Exception {
    String first = """
        {"firstName":"George","lastName":"Householder","address":"1 Shared Lane","city":"Madison","telephone":"6085550101"}
