    }

    @Test
    @WithMockUser(roles = "OWNER_ADMIN")
    void createOwnerMissingAndBlankFieldsListedInErrors() throws Exception {
        // firstName missing, address blank (whitespace), city empty -> all three must be reported.
        String body = """
